IDS = []
for i in range(12):
    for kind, data in ((T, TAU), (E, IZA), (C, ATF)):
        p, x, y = data[i]
        q = FORMS[(i + (0 if kind == T else 1 if kind == E else 2)) % 4].format(p=p)
        if kind == T: why = "‘%s’ صفت اور ‘%s’ موصوف ہے، اس لیے یہ مرکبِ توصیفی ہے۔" % (x, y)
        elif kind == E: why = "‘%s’ مضاف اور ‘%s’ مضاف الیہ ہے، اس لیے یہ مرکبِ اضافی ہے۔" % (x, y)
        else: why = "‘%s’ معطوف علیہ اور ‘%s’ معطوف ہے، دونوں عطف سے جڑے ہیں، اس لیے یہ مرکبِ عطفی ہے۔" % (x, y)
        lvl = "K" if kind == T else "U"
        IDS.append((lvl, q, kind, *others(kind), why))

